CREATE TABLE project_meta(id INTEGER PRIMARY KEY CHECK(id=1), manifest BLOB NOT NULL, revision INTEGER NOT NULL CHECK(revision>=0)) STRICT;
CREATE TABLE objects(hash TEXT PRIMARY KEY CHECK(length(hash)=64), data BLOB NOT NULL) STRICT;
CREATE TABLE canvas_root(id INTEGER PRIMARY KEY CHECK(id=1), body TEXT NOT NULL REFERENCES objects(hash) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE canvas_records(id TEXT PRIMARY KEY, path TEXT NOT NULL, kind TEXT NOT NULL, body TEXT NOT NULL REFERENCES objects(hash) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE canvas_nodes(id TEXT PRIMARY KEY REFERENCES canvas_records(id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE canvas_edges(id TEXT PRIMARY KEY REFERENCES canvas_records(id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE edge_endpoints(edge_id TEXT NOT NULL REFERENCES canvas_edges(id) DEFERRABLE INITIALLY DEFERRED, ordinal INTEGER NOT NULL CHECK(ordinal>=0), node_id TEXT NOT NULL REFERENCES canvas_nodes(id) DEFERRABLE INITIALLY DEFERRED, rate_x REAL NOT NULL, rate_y REAL NOT NULL, PRIMARY KEY(edge_id,ordinal)) STRICT;
CREATE INDEX endpoints_by_node ON edge_endpoints(node_id,edge_id);
CREATE TABLE group_members(parent_id TEXT NOT NULL REFERENCES canvas_nodes(id) DEFERRABLE INITIALLY DEFERRED, ordinal INTEGER NOT NULL CHECK(ordinal>=0), child_id TEXT NOT NULL REFERENCES canvas_nodes(id) DEFERRABLE INITIALLY DEFERRED, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE INDEX groups_by_child ON group_members(child_id,parent_id);
CREATE TABLE workflows(id TEXT PRIMARY KEY, ordinal INTEGER NOT NULL CHECK(ordinal>=0), body TEXT NOT NULL REFERENCES objects(hash) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE runs(id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id) DEFERRABLE INITIALLY DEFERRED, ordinal INTEGER NOT NULL CHECK(ordinal>=0), body TEXT NOT NULL REFERENCES objects(hash) DEFERRABLE INITIALLY DEFERRED, retry_of TEXT REFERENCES runs(id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE INDEX runs_by_workflow ON runs(workflow_id,ordinal);
CREATE TABLE run_sources(run_id TEXT NOT NULL REFERENCES runs(id) DEFERRABLE INITIALLY DEFERRED, ordinal INTEGER NOT NULL CHECK(ordinal>=0), source_id TEXT NOT NULL REFERENCES runs(id) DEFERRABLE INITIALLY DEFERRED, PRIMARY KEY(run_id,ordinal)) STRICT;
CREATE INDEX runs_by_source ON run_sources(source_id,run_id);
CREATE TABLE attachments(name TEXT PRIMARY KEY, body TEXT NOT NULL REFERENCES objects(hash) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE extensions(name TEXT PRIMARY KEY, body TEXT NOT NULL REFERENCES objects(hash) DEFERRABLE INITIALLY DEFERRED) STRICT;
